const rows = $input.all().map(i => i.json);

const groups = { book: [], movie: [], 'tv show': [] };
for (const r of rows) {
  (groups[r.kind] ??= []).push(r);
}

const icon = { book: '📖', movie: '🎬', 'tv show': '📺' };
const STATUSES = ['to watch', 'watching', 'done'];

const statusLinks = r => STATUSES.map(s => {
  const cls = s === r.status ? 'status-pill active' : 'status-pill';
  return s === r.status
    ? `<span class="${cls} status-${s.replace(/\s+/g, '-')}">${s}</span>`
    : `<a class="${cls} status-${s.replace(/\s+/g, '-')}" href="/webhook/update-status?id=${r.id}&status=${encodeURIComponent(s)}">${s}</a>`;
}).join('');

const deleteLink = r => `<a class="delete-link" href="/webhook/delete?id=${r.id}" onclick="return confirm('Delete this item?')">🗑</a>`;

const section = (kind, label) => {
  const items = groups[kind] || [];
  if (!items.length) return '';
  const rowsHtml = items.map(r => `
    <tr>
      <td>${r.title}</td>
      <td class="status-cell">${statusLinks(r)}</td>
      <td>${r.notes || ''}</td>
      <td>${new Date(r.added_at).toLocaleDateString()}</td>
      <td>${deleteLink(r)}</td>
    </tr>`).join('');
  return `
    <h2>${icon[kind]} ${label}</h2>
    <table>
      <thead><tr><th>Title</th><th>Status</th><th>Notes</th><th>Added</th><th></th></tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;
};

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Watchlist</title>
<style>
  :root {
    --ctp-red:#f38ba8; --ctp-peach:#fab387; --ctp-green:#a6e3a1; --ctp-sky:#89dceb;
    --ctp-mauve:#cba6f7; --ctp-text:#cdd6f4; --ctp-subtext0:#a6adc8;
    --ctp-surface0:#313244; --ctp-surface1:#45475a; --ctp-base:#1e1e2e; --ctp-mantle:#181825;
  }
  body { background: var(--ctp-base); color: var(--ctp-text); font-family: system-ui, sans-serif; padding: 2rem; max-width: 900px; margin: auto; }
  h1 { color: var(--ctp-mauve); }
  h2 { color: var(--ctp-sky); margin-top: 2rem; }
  a.add-link { color: var(--ctp-green); text-decoration: none; font-weight: 600; }
  table { width: 100%; border-collapse: collapse; background: var(--ctp-mantle); border-radius: .5rem; overflow: hidden; }
  th, td { padding: .6rem .8rem; text-align: left; border-bottom: 1px solid var(--ctp-surface0); }
  th { color: var(--ctp-subtext0); font-weight: 600; }
  .status-cell { display: flex; gap: .35rem; flex-wrap: wrap; }
  .status-pill { padding: .15rem .5rem; border-radius: .3rem; font-size: .8em; text-decoration: none; opacity: .45; border: 1px solid transparent; }
  .status-pill:hover { opacity: .75; }
  .status-pill.active { opacity: 1; font-weight: 600; }
  .status-to-watch { background: var(--ctp-surface1); color: var(--ctp-text); }
  .status-watching { background: var(--ctp-peach); color: var(--ctp-base); }
  .status-done { background: var(--ctp-green); color: var(--ctp-base); }
  .delete-link { text-decoration: none; opacity: .5; color: var(--ctp-red); }
  .delete-link:hover { opacity: 1; }
</style></head>
<body>
  <h1>📺 Watchlist</h1>
  <a class="add-link" href="/form/watchlist-add">+ Add something new</a>
  ${section('book', 'Books')}
  ${section('movie', 'Movies')}
  ${section('tv show', 'TV Shows')}
</body></html>`;

return [{ json: { html } }];
